import {withBunMcp,guardedWrite} from "../bun-mcp-client";
const root="C:/SSH/omar";
const app="server/apps/bun-webos";
const plugin="server/apps/bun-plugin-tailwind";
const manifest=await Bun.file(`${root}/package.json`).json();
const webos=await Bun.file(`${root}/${app}/package.json`).json();
const tailwind=await Bun.file(`${root}/${plugin}/package.json`).json();
const server=await Bun.file(`${root}/server/package.json`).json();
const lock=Bun.JSONC.parse(await Bun.file(`${root}/bun.lock`).text()) as any;
const backup=`${root}/server/var/workspace-migration`;
const appLock=await Bun.file(`${root}/${app}/bun.lock`).exists()?`${root}/${app}/bun.lock`:`${backup}/webos-lock-before.jsonc`;
const serverLock=await Bun.file(`${root}/server/bun.lock`).exists()?`${root}/server/bun.lock`:`${backup}/server-lock-before.jsonc`;
const previous=Bun.JSONC.parse(await Bun.file(appLock).text()) as any;
const system=Bun.JSONC.parse(await Bun.file(serverLock).text()) as any;
if(lock.lockfileVersion!==2||previous.lockfileVersion!==2||webos.name!=="@aphrody/bun-webos"||tailwind.name!=="@aphrody/bun-plugin-tailwind")throw new Error("Unexpected workspace identity or lock format");
manifest.workspaces=["server",app,plugin];
manifest.systemDependencies={...server.systemDependencies,...manifest.systemDependencies};
delete server.systemDependencies;
webos.dependencies[tailwind.name]="workspace:*";
tailwind.private=true;
lock.workspaces[app]={name:webos.name,version:webos.version,dependencies:webos.dependencies};
lock.workspaces[plugin]={name:tailwind.name,version:tailwind.version,dependencies:tailwind.dependencies,peerDependencies:tailwind.peerDependencies,optionalPeers:Object.keys(tailwind.peerDependenciesMeta??{}).filter(name=>tailwind.peerDependenciesMeta[name].optional)};
lock.packages={...previous.packages,...lock.packages,[webos.name]:[`${webos.name}@workspace:${app}`],[tailwind.name]:[`${tailwind.name}@workspace:${plugin}`]};
lock.system={...system.system,...lock.system};
for(const [name,source]of [["root",`${root}/bun.lock`],["webos",appLock],["server",serverLock]])if(!await Bun.file(`${backup}/${name}-lock-before.jsonc`).exists())await Bun.write(`${backup}/${name}-lock-before.jsonc`,Bun.file(source));
await withBunMcp("C:/",async call=>{
 for(const [path,value]of [["package.json",manifest],["server/package.json",server],[`${app}/package.json`,webos],[`${plugin}/package.json`,tailwind],["bun.lock",lock]] as const)await guardedWrite(call,`${root}/${path}`,JSON.stringify(value,null,2)+"\n");
});
console.log(JSON.stringify({workspaces:manifest.workspaces,seededPackages:Object.keys(lock.packages).length,versionsPreserved:true,backup}));
